style.content:
select,
::picker(select) {
  /* appearance: base-select; */
}

/* The arrow is a real part of the select: it can be placed and animated */
select::picker-icon {
  align-self: center;
  transition: rotate 0.2s;
}

select:open::picker-icon {
  rotate: 180deg;
}

select:open {
  outline-color: #4636c9;
  box-shadow: 0 0 0 3px #eceaff;
}

/* A copy of the chosen option, shown in the closed control */
selectedcontent {
  display: grid;
  grid-template-columns: auto 1fr;
  align-items: center;
  gap: 0 0.7rem;
}

/* The list (picker) */
::picker(select) {
  max-height: 17rem;
  margin-block: 0.4rem;
  padding: 0.35rem;
  border: 1px solid #cbc4b4;
  border-radius: 0.9rem;
  box-shadow: 0 24px 50px -20px rgb(28 27 34 / 0.45);
}

option {
  display: grid;
  grid-template-columns: auto 1fr;
  align-items: center;
  gap: 0 0.7rem;
  padding: 0.45rem 0.6rem;
  border-radius: 0.6rem;
}

option:hover,
option:focus-visible {
  background: #f3f0e8;
}

option:checked {
  background: #eceaff;
}

option:disabled {
  opacity: 0.4;
}

option::checkmark {
  display: none;
}

style.hiddenContent:
/* Preview frame shared by every view (from Lunch and Learn Simple's simple.css).
   Nothing in here is part of any demo. */
:root {
  font-family: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', sans-serif;
  font-size: clamp(15px, 0.55vw + 9px, 21px);
  color: #1c1b22;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
}

:focus-visible {
  outline: 3px solid #1f6feb;
  outline-offset: 2px;
}

/* The demo area fills the preview. */
.stage {
  position: relative;
  height: 100vh;
  overflow: hidden;
  background: #fff;
}

/* Note shown by unsupported.js when the browser lacks the feature. */
.unsupported {
  position: absolute;
  left: 0.8rem;
  bottom: 0.8rem;
  z-index: 100;
  display: flex;
  align-items: baseline;
  gap: 0.45rem;
  max-width: min(26rem, calc(100% - 1.6rem));
  margin: 0;
  padding: 0.35rem 0.75rem;
  font-size: 0.72rem;
  line-height: 1.4;
  color: #b42318;
  background: rgb(253 233 230 / 0.95);
  border: 1px solid #f1b8b0;
  border-radius: 0.6rem;
  pointer-events: none;
}

.unsupported::before {
  content: '';
  flex: none;
  width: 0.45rem;
  height: 0.45rem;
  background: #e5372b;
  border-radius: 50%;
}

.unsupported b {
  color: #8f1d14;
}

/* Page and option-content looks only, shared by before and after.
   The control itself is styled on each page, in the code that is shown. */

.stage {
  display: grid;
  place-items: start center;
  padding-top: 4rem;
  background: #f8f6f1;
}

.field {
  width: 24rem;
  padding: 1.4rem 1.5rem 1.6rem;
  background: #fff;
  border: 1px solid #e4dfd4;
  border-radius: 1.1rem;
  box-shadow: 0 20px 50px -30px rgb(28 27 34 / 0.5);
}

.field-control {
  position: relative;
}

.field-control + .field-control {
  margin-top: 1.2rem;
}

.field label {
  display: block;
  margin-bottom: 0.4rem;
  font-weight: 700;
}

/* A person: avatar, name, role (inside options and the closed control) */
.field img {
  grid-row: span 2;
  width: 2.4rem;
  height: 2.4rem;
  border-radius: 50%;
}

.field small {
  grid-column: 2;
  font-size: 0.8rem;
  color: #77748a;
}

/* The separator inside <small> is only there for the plain native select, which shows the
   option's text ("Ava Lindqvist · Design lead"). Where the select is customizable, the role
   gets its own line and the separator is in the way. */
.field small span {
  display: none;
}

/* The closed control: the box, styled as far as a native select lets us. It is kept out of the
   editors so that only the new feature is on display, and the code on the page can override it
   (plain `select` selectors). */

select {
  width: 100%;
  min-height: 3.6rem;
  padding: 0.4rem 0.8rem;
  font: inherit;
  color: inherit;
  background: #fff;
  border-radius: 0.8rem;
  cursor: pointer;

  /* A native select's arrow is painted at the inner edge of the border and no padding can
     reach it, so a wide right border is the only way to move it away from the corner. The
     visible edge of the control is drawn with an outline, which leaves that border free. */
  border: 0;
  border-right: 1rem solid transparent;
  outline: 1px solid #cbc4b4;
  outline-offset: -1px;
}

select:focus-visible {
  outline-color: #4636c9;
  box-shadow: 0 0 0 3px #eceaff;
}

/* Once the arrow is a real element it is laid out inside that wide border, so it comes back */
select::picker-icon {
  content: url("https://stepan-fielmann.github.io/wey/images/arrow.svg");
  margin-right: -0.75rem;
}

script.hiddenContent:
// A small note in the preview when the browser lacks the feature a modern view shows.
// `support` comes from feature.js: { css: 'display: grid-lanes' } or { api: 'popover' }.
function showUnsupported(support) {
  const API = { popover: () => 'showPopover' in HTMLElement.prototype };
  const ok = support.api ? API[support.api]() : CSS.supports(support.css);
  if (ok) return;
  const note = document.createElement('p');
  note.className = 'unsupported';
  const name = document.createElement('b');
  name.textContent = support.feature;
  const text = document.createElement('span');
  text.append(name, ' isn’t supported in this browser.' + (support.hint ? ` ${support.hint}` : ''));
  note.append(text);
  (document.querySelector('.stage') ?? document.body).prepend(note);
}

